import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { ApisEntity } from "#/modules/source/schema/entities/apis.entity.ts";
import * as Apis from "#/modules/source/schema/types/apis/index.ts";

/**
 * Repository of Apis: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class ApisRepository
  extends EntityRepository<
    ApisEntity,
    Apis.Types.ApisSortableField,
    Apis.Types.ApisEditableField,
    Apis.Types.ApisSelectableField,
    Apis.Types.IApisCreatable
  >
  implements IUpdatableRepository<ApisEntity, Apis.Types.IApisUpdatable>
{
  constructor(
    @InjectRepository(ApisEntity)
    repository: Repository<ApisEntity>,
  ) {
    super(repository, Apis.Config.APIS_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(id: string, data: Apis.Types.IApisUpdatable): Promise<ApisEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the apis with this source id (unique). */
  async findBySource(sourceId: NonNullable<ApisEntity["sourceId"]>): Promise<ApisEntity | null> {
    return await this.findOne({ sourceId, deletedAt: IsNull() });
  }
}
